arguments.content:
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

provider "aws" {
  region                      = var.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = false
  s3_use_path_style           = true

  endpoints {
    acm            = var.aws_endpoint_url
    cloudwatchlogs = var.aws_endpoint_url
    cognitoidp     = var.aws_endpoint_url
    dynamodb       = var.aws_endpoint_url
    ec2            = var.aws_endpoint_url
    ecs            = var.aws_endpoint_url
    elasticache    = var.aws_endpoint_url
    elbv2          = var.aws_endpoint_url
    iam            = var.aws_endpoint_url
    kms            = var.aws_endpoint_url
    lambda         = var.aws_endpoint_url
    rds            = var.aws_endpoint_url
    s3             = var.aws_endpoint_url
    scheduler      = var.aws_endpoint_url
    sqs            = var.aws_endpoint_url
    sts            = var.aws_endpoint_url
  }

  default_tags {
    tags = {
      ClearLedgerDeployment = var.resource_prefix
      Project               = "clearledger"
      ManagedBy             = "terraform"
    }
  }
}

variable "resource_prefix" {
  type        = string
  description = "Unique prefix for every resource of this deployment."
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.42.0.0/16"
}

data "aws_caller_identity" "current" {}

locals {
  p          = var.resource_prefix
  account_id = data.aws_caller_identity.current.account_id
  azs        = ["${var.region}a", "${var.region}b"]

  public_cidrs  = [cidrsubnet(var.vpc_cidr, 8, 0), cidrsubnet(var.vpc_cidr, 8, 1)]
  private_cidrs = [cidrsubnet(var.vpc_cidr, 8, 10), cidrsubnet(var.vpc_cidr, 8, 11)]
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "${local.p}-vpc" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.p}-igw" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "${local.p}-public-${local.azs[count.index]}", Tier = "public" }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = { Name = "${local.p}-private-${local.azs[count.index]}", Tier = "private" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = { Name = "${local.p}-public-rt" }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.p}-private-rt" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Inline ingress/egress blocks are used on purpose: Terraform
# then owns the complete rule set and removes any out-of-band rule (for
# example an unrestricted 0.0.0.0/0 egress) on the next apply.
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.p}-alb-sg"
  description = "ClearLedger ALB: HTTP 80 in from the internet, 8080 out to the API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks on 8080 inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-alb-sg" }
}

resource "aws_security_group" "ecs" {
  name        = "${local.p}-ecs-sg"
  description = "ClearLedger API tasks: 8080 from the ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API traffic from the ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "PostgreSQL inside the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Valkey inside the VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "AWS control plane (HTTPS)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "AWS control plane (local endpoint)"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${local.p}-ecs-sg" }
}

resource "aws_security_group" "rds" {
  name        = "${local.p}-rds-sg"
  description = "ClearLedger PostgreSQL: 5432 from the API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "Responses inside the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-rds-sg" }
}

resource "aws_security_group" "valkey" {
  name        = "${local.p}-valkey-sg"
  description = "ClearLedger Valkey: 6379 from the API tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "Responses inside the VPC only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-valkey-sg" }
}

locals {
  kms_purposes = {
    database   = "RDS PostgreSQL storage encryption"
    messaging  = "SQS main queue and DLQ encryption"
    projection = "DynamoDB projection table encryption"
    audit      = "S3 audit archive encryption"
  }

  log_groups = {
    api       = "/clearledger/${var.resource_prefix}/api"
    projector = "/clearledger/${var.resource_prefix}/projector"
    relay     = "/clearledger/${var.resource_prefix}/outbox-relay"
    archiver  = "/clearledger/${var.resource_prefix}/audit-archiver"
  }

  # Per-workload log group ARNs (group itself + its streams).
  log_arns = {
    for k, name in local.log_groups : k => [
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}",
      "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}:*",
    ]
  }
}

resource "aws_kms_key" "this" {
  for_each = local.kms_purposes

  description             = "${var.resource_prefix} ClearLedger ${each.key} key: ${each.value}"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = { Name = "${var.resource_prefix}-${each.key}" }
}

resource "aws_kms_alias" "this" {
  for_each = local.kms_purposes

  name          = "alias/${var.resource_prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_groups

  name              = each.value
  retention_in_days = 14

  tags = { Name = "${var.resource_prefix}-${each.key}-logs" }
}

# ---------------------------------------------------------------- RDS ----
resource "aws_db_subnet_group" "main" {
  name        = "${local.p}-db-subnets"
  description = "ClearLedger PostgreSQL private subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = { Name = "${local.p}-db-subnets" }
}

resource "aws_db_instance" "main" {
  identifier             = "${local.p}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  apply_immediately      = true

  tags = { Name = "${local.p}-postgres" }

  lifecycle {
    # Never let cosmetic emulator differences force a replacement of the
    # system of record.
    ignore_changes = [engine_version, allocated_storage, port, availability_zone]
  }
}

# ----------------------------------------------------------- DynamoDB ----
resource "aws_dynamodb_table" "projections" {
  name         = "${local.p}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = { Name = "${local.p}-projections" }
}

# ------------------------------------------------------------- Valkey ----
resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.p}-cache-subnets"
  description = "ClearLedger Valkey private subnets"
  subnet_ids  = aws_subnet.private[*].id

  tags = { Name = "${local.p}-cache-subnets" }
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id       = "${local.p}-valkey"
  description                = "ClearLedger projection cache"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  automatic_failover_enabled = false
  apply_immediately          = true

  tags = { Name = "${local.p}-valkey" }

  lifecycle {
    # The emulator may serve the cache on a different proxy port than the
    # requested one; never replace the cache because of that.
    ignore_changes = [port, engine_version, parameter_group_name]
  }
}

# ----------------------------------------------------------------- S3 ----
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.p}-audit-archive"
  force_destroy = true

  tags = { Name = "${local.p}-audit-archive" }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------- SQS ----
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.p}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600

  tags = { Name = "${local.p}-events-dlq" }
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.p}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = { Name = "${local.p}-events" }
}

locals {
  queue_arn  = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  index_arn  = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn
  objects    = "${aws_s3_bucket.audit.arn}/*"
  audit_objs = "${aws_s3_bucket.audit.arn}/ledger-audit/*"

  kms = { for k, v in aws_kms_key.this : k => v.arn }

  fn_names = {
    projector = "${var.resource_prefix}-projector"
    relay     = "${var.resource_prefix}-outbox-relay"
    archiver  = "${var.resource_prefix}-audit-archiver"
  }
  fn_arns = { for k, n in local.fn_names : k => "arn:aws:lambda:${var.region}:${local.account_id}:function:${n}" }

  sqs_data_actions = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_data_actions = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_data_actions  = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  kms_use_actions  = ["kms:Decrypt", "kms:GenerateDataKey"]
  log_write        = ["logs:CreateLogStream", "logs:PutLogEvents"]
  log_allow        = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]

  # ------------------------------------------------------------------
  # Reusable deny guardrails
  # ------------------------------------------------------------------
  deny_all_sqs = {
    Sid      = "DenyAllQueueData"
    Effect   = "Deny"
    Action   = local.sqs_data_actions
    Resource = [local.queue_arn, local.dlq_arn]
  }
  deny_all_ddb = {
    Sid      = "DenyProjectionTable"
    Effect   = "Deny"
    Action   = local.ddb_data_actions
    Resource = [local.table_arn, local.index_arn]
  }
  deny_all_s3 = {
    Sid      = "DenyAuditBucket"
    Effect   = "Deny"
    Action   = local.s3_data_actions
    Resource = [local.bucket_arn, local.objects]
  }

  deny_kms = {
    for role, keys in {
      ecs_execution = ["database", "messaging", "projection", "audit"]
      ecs_task      = ["database", "audit"]
      projector     = ["database", "audit"]
      relay         = ["projection", "audit"]
      archiver      = ["messaging", "projection"]
      scheduler     = ["database", "messaging", "projection", "audit"]
      } : role => {
      Sid      = "DenyForeignKmsKeys"
      Effect   = "Deny"
      Action   = local.kms_use_actions
      Resource = [for k in keys : local.kms[k]]
    }
  }

  deny_logs = {
    for role, groups in {
      ecs_execution = ["projector", "relay", "archiver"]
      ecs_task      = ["projector", "relay", "archiver"]
      projector     = ["api", "relay", "archiver"]
      relay         = ["api", "projector", "archiver"]
      archiver      = ["api", "projector", "relay"]
      scheduler     = ["api", "projector", "relay", "archiver"]
      } : role => {
      Sid      = "DenyForeignLogGroups"
      Effect   = "Deny"
      Action   = local.log_write
      Resource = flatten([for g in groups : local.log_arns[g]])
    }
  }

  policies = {
    ecs_execution = [
      {
        Sid      = "ApiLogStreams"
        Effect   = "Allow"
        Action   = local.log_allow
        Resource = local.log_arns["api"]
      },
      local.deny_all_sqs,
      local.deny_all_ddb,
      local.deny_all_s3,
      local.deny_kms["ecs_execution"],
      local.deny_logs["ecs_execution"],
    ]

    ecs_task = [
      {
        Sid      = "PublishDomainEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.table_arn, local.index_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["projection"]]
      },
      {
        Sid      = "ApiLogStreams"
        Effect   = "Allow"
        Action   = local.log_allow
        Resource = local.log_arns["api"]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDlq"
        Effect   = "Deny"
        Action   = local.sqs_data_actions
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.index_arn]
      },
      local.deny_all_s3,
      local.deny_kms["ecs_task"],
      local.deny_logs["ecs_task"],
    ]

    projector = [
      {
        Sid      = "ConsumeMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ForwardToDlq"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = [local.table_arn, local.index_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["projection"]]
      },
      {
        Sid      = "ProjectorLogStreams"
        Effect   = "Allow"
        Action   = local.log_allow
        Resource = local.log_arns["projector"]
      },
      {
        Sid      = "DenyPublishMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyConsumeDlq"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionDeletes"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.index_arn]
      },
      local.deny_all_s3,
      local.deny_kms["projector"],
      local.deny_logs["projector"],
    ]

    relay = [
      {
        Sid      = "PublishDomainEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "UseMessagingAndDatabaseKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["database"]]
      },
      {
        Sid      = "RelayLogStreams"
        Effect   = "Allow"
        Action   = local.log_allow
        Resource = local.log_arns["relay"]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDlq"
        Effect   = "Deny"
        Action   = local.sqs_data_actions
        Resource = [local.dlq_arn]
      },
      local.deny_all_ddb,
      local.deny_all_s3,
      local.deny_kms["relay"],
      local.deny_logs["relay"],
    ]

    archiver = [
      {
        Sid      = "AppendAuditObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource = [local.audit_objs]
      },
      {
        Sid      = "AuditBucketMetadata"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [local.bucket_arn]
      },
      {
        Sid      = "UseAuditAndDatabaseKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["audit"], local.kms["database"]]
      },
      {
        Sid      = "ArchiverLogStreams"
        Effect   = "Allow"
        Action   = local.log_allow
        Resource = local.log_arns["archiver"]
      },
      {
        Sid      = "DenyAuditDeletes"
        Effect   = "Deny"
        Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource = [local.bucket_arn, local.objects]
      },
      {
        Sid      = "DenyBucketLevelPut"
        Effect   = "Deny"
        Action   = ["s3:PutObject"]
        Resource = [local.bucket_arn]
      },
      local.deny_all_sqs,
      local.deny_all_ddb,
      local.deny_kms["archiver"],
      local.deny_logs["archiver"],
    ]

    scheduler = [
      {
        Sid      = "InvokeScheduledWorkers"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = [local.fn_arns["relay"], local.fn_arns["archiver"]]
      },
      {
        Sid      = "DenyInvokeProjector"
        Effect   = "Deny"
        Action   = ["lambda:InvokeFunction"]
        Resource = [local.fn_arns["projector"], "${local.fn_arns["projector"]}:*"]
      },
      local.deny_all_sqs,
      local.deny_all_ddb,
      local.deny_all_s3,
      local.deny_kms["scheduler"],
      local.deny_logs["scheduler"],
    ]
  }

  role_principals = {
    ecs_execution = "ecs-tasks.amazonaws.com"
    ecs_task      = "ecs-tasks.amazonaws.com"
    projector     = "lambda.amazonaws.com"
    relay         = "lambda.amazonaws.com"
    archiver      = "lambda.amazonaws.com"
    scheduler     = "scheduler.amazonaws.com"
  }

  role_names = {
    ecs_execution = "${var.resource_prefix}-ecs-execution"
    ecs_task      = "${var.resource_prefix}-ecs-task"
    projector     = "${var.resource_prefix}-projector"
    relay         = "${var.resource_prefix}-outbox-relay"
    archiver      = "${var.resource_prefix}-audit-archiver"
    scheduler     = "${var.resource_prefix}-scheduler"
  }
}

resource "aws_iam_role" "this" {
  for_each = local.role_principals

  name = local.role_names[each.key]
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid       = "TrustedService"
      Effect    = "Allow"
      Principal = { Service = each.value }
      Action    = "sts:AssumeRole"
    }]
  })
  force_detach_policies = true

  tags = { Name = local.role_names[each.key], Workload = each.key }
}

resource "aws_iam_role_policy" "this" {
  for_each = local.policies

  name = "${local.role_names[each.key]}-least-privilege"
  role = aws_iam_role.this[each.key].id
  policy = jsonencode({
    Version   = "2012-10-17"
    Statement = each.value
  })
}

# Terraform owns the complete inline/attached policy set of every workload
# role: any out-of-band inline policy or attachment is removed on apply.
resource "aws_iam_role_policies_exclusive" "this" {
  for_each = local.policies

  role_name    = aws_iam_role.this[each.key].name
  policy_names = [aws_iam_role_policy.this[each.key].name]
}

resource "aws_iam_role_policy_attachments_exclusive" "this" {
  for_each = local.policies

  role_name   = aws_iam_role.this[each.key].name
  policy_arns = []
}

locals {
  database_url = "postgres://${var.db_username}:${urlencode(var.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  valkey_host  = aws_elasticache_replication_group.valkey.primary_endpoint_address
  valkey_port  = aws_elasticache_replication_group.valkey.port
  valkey_url   = "redis://${local.valkey_host}:${local.valkey_port}"

  issuer_url = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}"
  jwks_url   = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  audiences  = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.this[k].id])

  base_env = {
    AWS_REGION            = var.region
    AWS_DEFAULT_REGION    = var.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = var.aws_endpoint_url
  }

  api_env = merge(local.base_env, {
    PORT                 = "8080"
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CACHE_TTL_SECONDS    = "90"
    AUTH_ISSUER          = local.issuer_url
    AUTH_AUDIENCES       = local.audiences
    AUTH_JWKS_URL        = local.jwks_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["api"].name
  })

  projector_env = merge(local.base_env, {
    PROJECTION_TABLE     = aws_dynamodb_table.projections.name
    VALKEY_URL           = local.valkey_url
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
  })

  relay_env = merge(local.base_env, {
    DATABASE_URL         = local.database_url
    SQS_QUEUE_URL        = aws_sqs_queue.main.url
    OUTBOX_BATCH_SIZE    = "50"
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
  })

  archiver_env = merge(local.base_env, {
    DATABASE_URL         = local.database_url
    AUDIT_BUCKET         = aws_s3_bucket.audit.bucket
    AUDIT_PREFIX         = "ledger-audit/"
    CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
  })
}

# ---------------------------------------------------------------- ALB ----
resource "aws_lb" "api" {
  name               = "${local.p}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]

  tags = { Name = "${local.p}-alb" }
}

resource "aws_lb_target_group" "api" {
  name        = "${local.p}-api-tg"
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 5

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = { Name = "${local.p}-api-tg" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = { Name = "${local.p}-http" }
}

# ---------------------------------------------------------------- ECS ----
resource "aws_ecs_cluster" "main" {
  name = "${local.p}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = { Name = "${local.p}-cluster" }
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.p}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.this["ecs_execution"].arn
  task_role_arn            = aws_iam_role.this["ecs_task"].arn

  container_definitions = jsonencode([{
    name      = "api"
    image     = var.api_image
    essential = true
    portMappings = [{
      containerPort = 8080
      hostPort      = 8080
      protocol      = "tcp"
    }]
    environment = [for k in sort(keys(local.api_env)) : { name = k, value = local.api_env[k] }]
    logConfiguration = {
      logDriver = "awslogs"
      options = {
        awslogs-group         = aws_cloudwatch_log_group.this["api"].name
        awslogs-region        = var.region
        awslogs-stream-prefix = "api"
      }
    }
  }])

  tags = { Name = "${local.p}-api", ImageId = var.api_image_id }
}

resource "aws_ecs_service" "api" {
  name                              = "${local.p}-api"
  cluster                           = aws_ecs_cluster.main.id
  task_definition                   = aws_ecs_task_definition.api.arn
  launch_type                       = "FARGATE"
  desired_count                     = 2
  health_check_grace_period_seconds = 30
  wait_for_steady_state             = false

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  tags = { Name = "${local.p}-api" }

  depends_on = [aws_lb_listener.http, aws_iam_role_policy.this]
}

# ------------------------------------------------------------- Lambda ----
resource "aws_lambda_function" "projector" {
  function_name = local.fn_names["projector"]
  package_type  = "Image"
  image_uri     = var.projector_image
  role          = aws_iam_role.this["projector"].arn
  timeout       = 3
  memory_size   = 512

  environment {
    variables = local.projector_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  tags = { Name = local.fn_names["projector"], ImageId = var.projector_image_id }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "relay" {
  function_name = local.fn_names["relay"]
  package_type  = "Image"
  image_uri     = var.relay_image
  role          = aws_iam_role.this["relay"].arn
  timeout       = 60
  memory_size   = 512

  environment {
    variables = local.relay_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  tags = { Name = local.fn_names["relay"], ImageId = var.relay_image_id }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_function" "archiver" {
  function_name = local.fn_names["archiver"]
  package_type  = "Image"
  image_uri     = var.archiver_image
  role          = aws_iam_role.this["archiver"].arn
  timeout       = 120
  memory_size   = 512

  environment {
    variables = local.archiver_env
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  tags = { Name = local.fn_names["archiver"], ImageId = var.archiver_image_id }

  depends_on = [aws_iam_role_policy.this]
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]

  tags = { Name = "${local.p}-projector-esm" }
}

# ---------------------------------------------------------- Scheduler ----
resource "aws_scheduler_schedule" "outbox" {
  name        = "${local.p}-outbox-relay"
  group_name  = "default"
  description = "Relay committed outbox rows to SQS every minute"
  state       = "ENABLED"

  schedule_expression = "rate(1 minute)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "scheduler", job = "outbox-relay" })
  }
}

resource "aws_scheduler_schedule" "archive" {
  name        = "${local.p}-audit-archiver"
  group_name  = "default"
  description = "Archive published settlement events to S3 every five minutes"
  state       = "ENABLED"

  schedule_expression = "rate(5 minutes)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.this["scheduler"].arn
    input    = jsonencode({ source = "scheduler", job = "audit-archiver" })
  }
}

# ------------------------------------------------------------ Cognito ----
resource "aws_cognito_user_pool" "main" {
  name = "${local.p}-users"

  tags = { Name = "${local.p}-users" }
}

resource "aws_cognito_resource_server" "clearledger" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.p}-clearledger-api"

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }
  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }
  scope {
    scope_name        = "admin"
    scope_description = "Rebuild settlement projections"
  }
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(["read", "write", "admin"])

  name                                 = "${local.p}-${each.key}-client"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/${each.key}"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]

  depends_on = [aws_cognito_resource_server.clearledger]
}

output "manifest" {
  sensitive = true
  value = {
    resource_prefix = var.resource_prefix
    region          = var.region
    service_url     = "http://${aws_lb.api.dns_name}"

    network = {
      vpc_id             = aws_vpc.main.id
      public_subnet_ids  = aws_subnet.public[*].id
      private_subnet_ids = aws_subnet.private[*].id
      security_group_ids = {
        alb    = aws_security_group.alb.id
        ecs    = aws_security_group.ecs.id
        rds    = aws_security_group.rds.id
        valkey = aws_security_group.valkey.id
      }
    }

    ingress = {
      alb_arn          = aws_lb.api.arn
      alb_dns_name     = aws_lb.api.dns_name
      listener_arn     = aws_lb_listener.http.arn
      target_group_arn = aws_lb_target_group.api.arn
      container_port   = 8080
    }

    compute = {
      cluster_arn         = aws_ecs_cluster.main.arn
      cluster_name        = aws_ecs_cluster.main.name
      service_arn         = aws_ecs_service.api.id
      service_name        = aws_ecs_service.api.name
      task_definition_arn = aws_ecs_task_definition.api.arn
      desired_count       = aws_ecs_service.api.desired_count
    }

    database = {
      instance_id  = aws_db_instance.main.identifier
      instance_arn = aws_db_instance.main.arn
      endpoint     = aws_db_instance.main.address
      port         = aws_db_instance.main.port
      db_name      = var.db_name
      username     = var.db_username
    }

    messaging = {
      queue_name                = aws_sqs_queue.main.name
      queue_url                 = aws_sqs_queue.main.url
      queue_arn                 = aws_sqs_queue.main.arn
      dlq_name                  = aws_sqs_queue.dlq.name
      dlq_url                   = aws_sqs_queue.dlq.url
      dlq_arn                   = aws_sqs_queue.dlq.arn
      event_source_mapping_uuid = aws_lambda_event_source_mapping.projector.uuid
      max_receive_count         = 4
    }

    workers = {
      projector = {
        function_name = aws_lambda_function.projector.function_name
        function_arn  = aws_lambda_function.projector.arn
      }
      outbox_relay = {
        function_name = aws_lambda_function.relay.function_name
        function_arn  = aws_lambda_function.relay.arn
      }
      audit_archiver = {
        function_name = aws_lambda_function.archiver.function_name
        function_arn  = aws_lambda_function.archiver.arn
      }
    }

    projections = {
      table_name = aws_dynamodb_table.projections.name
      table_arn  = aws_dynamodb_table.projections.arn
      gsi_name   = "AccountIndex"
    }

    cache = {
      cluster_id = aws_elasticache_replication_group.valkey.id
      engine     = "valkey"
      endpoint   = local.valkey_host
      port       = local.valkey_port
    }

    audit = {
      bucket_name = aws_s3_bucket.audit.bucket
      bucket_arn  = aws_s3_bucket.audit.arn
      prefix      = "ledger-audit/"
    }

    schedules = {
      outbox_schedule_name  = aws_scheduler_schedule.outbox.name
      outbox_schedule_arn   = aws_scheduler_schedule.outbox.arn
      archive_schedule_name = aws_scheduler_schedule.archive.name
      archive_schedule_arn  = aws_scheduler_schedule.archive.arn
    }

    auth = {
      user_pool_id               = aws_cognito_user_pool.main.id
      user_pool_arn              = aws_cognito_user_pool.main.arn
      issuer_url                 = local.issuer_url
      token_endpoint             = "${var.aws_endpoint_url}/cognito-idp/oauth2/token"
      resource_server_identifier = aws_cognito_resource_server.clearledger.identifier
      clients = {
        for k in ["read", "write", "admin"] : k => {
          client_id     = aws_cognito_user_pool_client.this[k].id
          client_secret = aws_cognito_user_pool_client.this[k].client_secret
          scope         = "clearledger/${k}"
        }
      }
    }

    iam = {
      ecs_execution_role_arn = aws_iam_role.this["ecs_execution"].arn
      ecs_task_role_arn      = aws_iam_role.this["ecs_task"].arn
      projector_role_arn     = aws_iam_role.this["projector"].arn
      relay_role_arn         = aws_iam_role.this["relay"].arn
      archiver_role_arn      = aws_iam_role.this["archiver"].arn
      scheduler_role_arn     = aws_iam_role.this["scheduler"].arn
    }

    kms = {
      database_arn   = aws_kms_key.this["database"].arn
      messaging_arn  = aws_kms_key.this["messaging"].arn
      projection_arn = aws_kms_key.this["projection"].arn
      audit_arn      = aws_kms_key.this["audit"].arn
    }

    logs = {
      api_log_group       = aws_cloudwatch_log_group.this["api"].name
      projector_log_group = aws_cloudwatch_log_group.this["projector"].name
      relay_log_group     = aws_cloudwatch_log_group.this["relay"].name
      archiver_log_group  = aws_cloudwatch_log_group.this["archiver"].name
    }
  }
}

