    if t==b'-': raise Exception(r.decode())
    if t==b':': return int(r)
    if t==b'$':
        n=int(r)
        if n<0: return None
        d=f.read(n+2); return d[:-2].decode()
    if t==b'*':
        n=int(r); return None if n<0 else [read(f) for _ in range(n)]
